def transform(grid):
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    shape = [[0] * (c1-c0+1) for _ in range(r1-r0+1)]
    for r, c in cells:
        shape[r-r0][c-c0] = 8

    n = len(markers)
    out = [[0] * (len(shape[0])*n) for _ in range(len(shape)+1 if n == 3 else len(shape))]
    offset = 1 if n == 3 else 0
    for k in range(n):
        for r in range(len(shape)):
            for c in range(len(shape[0])):
                out[r+offset][k*len(shape[0])+c] = shape[r][c]
    return out
